import { after } from "next/server";
import { requireWorkspace } from "@/lib/auth";
import { modelForSettings } from "@/lib/ai/provider";
import { VOICE_CALL_TITLE } from "@/lib/ai/voice-access";
import { MAX_RECORD_BYTES, callRecordSchema, summarizeCall } from "@/lib/ai/voice-call-record";

export async function POST(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  const body = await request.text();
  if (new TextEncoder().encode(body).length > MAX_RECORD_BYTES) return Response.json({ error: "Call record is too large" }, { status: 413 });
  let json: unknown = null;
  try { json = JSON.parse(body); } catch { json = null; }
  const parsed = callRecordSchema.safeParse(json);
  if (!parsed.success) return Response.json({ error: "Invalid call record" }, { status: 400 });
  const { id, conversationId, durationSeconds, transcript, tasks } = parsed.data;
  const { supabase, workspace, settings } = context;
  const conversation = await supabase.from("conversations").select("id, deleted_at").eq("workspace_id", workspace.id).eq("id", conversationId).maybeSingle();
  if (conversation.error) throw conversation.error;
  if (conversation.data?.deleted_at) return Response.json({ error: "Conversation unavailable" }, { status: 404 });
  if (!conversation.data) {
    const created = await supabase.from("conversations").insert({ id: conversationId, workspace_id: workspace.id, title: VOICE_CALL_TITLE });
    if (created.error && created.error.code !== "23505") throw created.error;
  }
  const saved = await supabase.from("voice_calls").insert({ id, workspace_id: workspace.id, conversation_id: conversationId, duration_seconds: durationSeconds, transcript, tasks, request_ids: tasks.map(task => task.requestId) });
  if (saved.error?.code === "23505") return Response.json({ id });
  if (saved.error) throw saved.error;
  after(() => summarizeCall(supabase, { workspaceId: workspace.id, callId: id, conversationId, transcript, model: () => modelForSettings(settings, "chat") }));
  return Response.json({ id }, { status: 201 });
}
import { z } from "zod";
import { generateText, type LanguageModel } from "ai";
import type { SupabaseClient } from "@supabase/supabase-js";
import { cleanTitle, saveTitle } from "./chat-title";

export const MAX_TRANSCRIPT_BYTES = 40_000;
export const MAX_RECORD_BYTES = 64_000;
export const SUMMARY_INPUT_CHARS = 12_000;

export const callTurnSchema = z.object({ role: z.enum(["user", "assistant"]), text: z.string().trim().min(1).max(4000) }).strict();
export const callTaskSchema = z.object({
  requestId: z.uuid(), text: z.string().max(300), title: z.string().max(120).optional(), status: z.enum(["running", "done", "failed", "canceled"]),
}).strict();
export type CallTurn = z.infer<typeof callTurnSchema>;
export type CallTaskRecord = z.infer<typeof callTaskSchema>;

const bytes = (value: unknown) => new TextEncoder().encode(JSON.stringify(value)).length;

export const callRecordSchema = z.object({
  id: z.uuid(),
  conversationId: z.uuid(),
  durationSeconds: z.number().int().min(0).max(86_400),
  transcript: z.array(callTurnSchema).min(1).max(400).refine(turns => bytes(turns) <= MAX_TRANSCRIPT_BYTES, "Transcript is too large"),
  tasks: z.array(callTaskSchema).max(30),
}).strict();
export type CallRecordInput = z.infer<typeof callRecordSchema>;

export function boundTranscript(turns: { role: "user" | "assistant"; text: string }[]): CallTurn[] {
  const kept = turns.flatMap(turn => turn.text.trim() ? [{ role: turn.role, text: turn.text.trim().slice(0, 4000) }] : []).slice(-400);
  while (kept.length > 1 && bytes(kept) > MAX_TRANSCRIPT_BYTES) kept.shift();
  return kept;
}

