  expect(callRecordSchema.safeParse(valid).success).toBe(true);
  for (const bad of [{ ...valid, id: "x" }, { ...valid, durationSeconds: -1 }, { ...valid, durationSeconds: 1.5 }, { ...valid, transcript: [] },
