    { ...valid, tasks: [{ requestId: id, text: "x", status: "weird" }] }, { ...valid, tasks: Array(31).fill({ requestId: id, text: "x", status: "done" }) }])
    expect(callRecordSchema.safeParse(bad).success).toBe(false);
