import { chromium } from "@playwright/test";
import { execFileSync } from "node:child_process";
const SC = process.argv[2];
const ws = "79aad90a-62e6-412b-ac5f-7ab3e8e1f2f3", other = "0db698d1-02ac-4fa9-8995-dfc28e19369d";
const rec = (id, workspaceId) => ({ record: { id, workspaceId, conversationId: crypto.randomUUID(), durationSeconds: 42, transcript: [{ role: "user", text: "How much at Netto?" }, { role: "assistant", text: "42 euros" }], tasks: [] }, rejections: 0 });
const psql = q => execFileSync("docker", ["exec", "moneo-qa-db-1", "psql", "-U", "postgres", "-tAc", q]).toString().trim();
const browser = await chromium.launch();
const ctx = await browser.newContext({ storageState: "e2e/.auth.json", viewport: { width: 1280, height: 800 } });
const page = await ctx.newPage();
page.on("pageerror", e => console.log("PAGEERROR", e.message));
await page.goto("http://localhost:3100/");
await page.waitForLoadState("networkidle");
const put = entries => page.evaluate(async entries => {
  const db = await new Promise((res, rej) => { const r = indexedDB.open("moneo-call-records", 1); r.onupgradeneeded = () => r.result.createObjectStore("records", { keyPath: "record.id" }); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
  await new Promise((res, rej) => { const t = db.transaction("records", "readwrite"); const s = t.objectStore("records"); entries.forEach(e => s.put(e)); t.oncomplete = res; t.onerror = rej; });
  db.close();
}, entries);
const count = () => page.evaluate(async () => { const db = await new Promise(res => { const r = indexedDB.open("moneo-call-records", 1); r.onsuccess = () => res(r.result); }); const n = await new Promise(res => { const r = db.transaction("records").objectStore("records").count(); r.onsuccess = () => res(r.result); }); db.close(); return n; });
const a = crypto.randomUUID(), b = crypto.randomUUID();
await put([rec(a, ws), rec(b, other)]);
await ctx.route("**/api/voice/calls", route => route.abort("internetdisconnected"));
await page.reload(); await page.waitForTimeout(2000);
console.log("pending note:", await page.getByText("will be saved when you're back online").count(), "in store:", await count());
await page.screenshot({ path: `${SC}/offline-light.png` });
await page.emulateMedia({ colorScheme: "dark" }); await page.screenshot({ path: `${SC}/offline-dark.png` });
await page.setViewportSize({ width: 390, height: 800 }); await page.screenshot({ path: `${SC}/offline-mobile.png` });
await page.setViewportSize({ width: 1280, height: 800 }); await page.emulateMedia({ colorScheme: "light" });
await ctx.unroute("**/api/voice/calls");
await page.evaluate(() => window.dispatchEvent(new Event("online"))); await page.waitForTimeout(3000);
console.log("saved rows for a:", psql(`select count(*) from voice_calls where id='${a}'`), "rows for b (other ws):", psql(`select count(*) from voice_calls where id='${b}'`), "in store:", await count());
console.log("saved note:", await page.getByText("Your call was saved.").count());
await page.screenshot({ path: `${SC}/saved-light.png` });
await page.evaluate(() => window.dispatchEvent(new Event("online"))); await page.waitForTimeout(1500);
console.log("rows for a after repeat flush:", psql(`select count(*) from voice_calls where id='${a}'`));
await browser.close();
JSEOF
mkdir -p .qa/shots/offline-note; cp "$TEMP/verify.mjs" ./verify-tmp.mjs; node verify-tmp.mjs .qa/shots/offline-note; rm verify-tmp.mjs

